using System;
using System.Runtime.InteropServices;
using System.Drawing;
using System.Drawing.Imaging;
using System.IO;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;

namespace ImagePipeline
{
    public class FeatureFlags
    {
        private readonly Dictionary<string, bool> _flags;
        private static FeatureFlags _instance;
        private static readonly object _lock = new object();

        private FeatureFlags()
        {
            _flags = new Dictionary<string, bool>
            {
                { "use_native_resize", true },
                { "enable_metadata_strip", true },
                { "allow_icc_profiles", false },
                { "use_managed_buffers", false },
                { "validate_dimensions", true }
            };
        }

        public static FeatureFlags Instance
        {
            get
            {
                if (_instance == null)
                {
                    lock (_lock)
                    {
                        if (_instance == null)
                            _instance = new FeatureFlags();
                    }
                }
                return _instance;
            }
        }

        public bool IsEnabled(string flag) =>
            _flags.ContainsKey(flag) && _flags[flag];

        public void SetFlag(string flag, bool value)
        {
            lock (_lock)
            {
                _flags[flag] = value;
            }
        }
    }

    internal static class NativeInterop
    {
        [DllImport("libimgproc.so", CallingConvention = CallingConvention.Cdecl)]
        internal static extern int native_resize(
            IntPtr srcBuffer, int srcWidth, int srcHeight, int srcStride,
            IntPtr dstBuffer, int dstWidth, int dstHeight, int dstStride,
            int channels);

        [DllImport("libimgproc.so", CallingConvention = CallingConvention.Cdecl)]
        internal static extern int native_compute_buffer_size(
            int width, int height, int channels);
    }

    public class ImageResizeRequest
    {
        public int TargetWidth { get; set; }
        public int TargetHeight { get; set; }
        public string InputPath { get; set; }
        public string OutputPath { get; set; }
    }

    public class DimensionValidator
    {
        private const int MaxDimension = 8192;
        private const int MinDimension = 1;

        public bool ValidateDimensions(int width, int height)
        {
            if (width < MinDimension || height < MinDimension)
                return false;
            if (width > MaxDimension || height > MaxDimension)
                return false;
            return true;
        }

        public bool ValidateBufferSize(int width, int height, int channels)
        {
            long totalSize = (long)width * height * channels;
            return totalSize <= int.MaxValue && totalSize > 0;
        }
    }

    public class NativeBufferManager : IDisposable
    {
        private IntPtr _buffer;
        private int _size;
        private bool _disposed;

        public IntPtr Buffer => _buffer;
        public int Size => _size;

        public bool Allocate(int width, int height, int channels)
        {
            int computedSize = ComputeAllocationSize(width, height, channels);
            if (computedSize <= 0)
                return false;

            _buffer = Marshal.AllocHGlobal(computedSize);
            _size = computedSize;
            return _buffer != IntPtr.Zero;
        }

        private int ComputeAllocationSize(int width, int height, int channels)
        {
            if (FeatureFlags.Instance.IsEnabled("use_managed_buffers"))
            {
                return width * height * channels;
            }

            // When using native buffers, query the native library for
            // the required buffer size including alignment padding
            int nativeSize = NativeInterop.native_compute_buffer_size(
                width, height, channels);
            return nativeSize;
        }

        public void Dispose()
        {
            if (!_disposed && _buffer != IntPtr.Zero)
            {
                Marshal.FreeHGlobal(_buffer);
                _buffer = IntPtr.Zero;
                _disposed = true;
            }
        }
    }

    public class ImageProcessor
    {
        private readonly DimensionValidator _validator;

        public ImageProcessor()
        {
            _validator = new DimensionValidator();
        }

        public byte[] ProcessResize(ImageResizeRequest request)
        {
            if (string.IsNullOrEmpty(request.InputPath))
                throw new ArgumentException("Input path required");

            string resolvedPath = Path.GetFullPath(request.InputPath);
            string allowedDir = Path.GetFullPath("/data/images");
            if (!resolvedPath.StartsWith(allowedDir + Path.DirectorySeparatorChar))
                throw new UnauthorizedAccessException("Path traversal blocked");

            if (FeatureFlags.Instance.IsEnabled("validate_dimensions"))
            {
                if (!_validator.ValidateDimensions(request.TargetWidth, request.TargetHeight))
                    throw new ArgumentException("Invalid target dimensions");
            }

            using (var srcImage = Image.FromFile(resolvedPath))
            {
                int srcWidth = srcImage.Width;
                int srcHeight = srcImage.Height;
                int channels = 4; // BGRA

                if (!_validator.ValidateBufferSize(request.TargetWidth, request.TargetHeight, channels))
                    throw new ArgumentException("Buffer size overflow");

                if (FeatureFlags.Instance.IsEnabled("use_native_resize"))
                {
                    return PerformNativeResize(srcImage, srcWidth, srcHeight,
                        request.TargetWidth, request.TargetHeight, channels);
                }
                else
                {
                    return PerformManagedResize(srcImage, request.TargetWidth, request.TargetHeight);
                }
            }
        }

        private byte[] PerformNativeResize(Image srcImage, int srcWidth, int srcHeight,
            int dstWidth, int dstHeight, int channels)
        {
            int srcStride = srcWidth * channels;
            int dstStride = dstWidth * channels;

            using (var srcBitmap = new Bitmap(srcImage))
            {
                BitmapData srcData = srcBitmap.LockBits(
                    new Rectangle(0, 0, srcWidth, srcHeight),
                    ImageLockMode.ReadOnly, PixelFormat.Format32bppArgb);

                try
                {
                    using (var dstBuffer = new NativeBufferManager())
                    {
                        if (!dstBuffer.Allocate(dstWidth, dstHeight, channels))
                            throw new OutOfMemoryException("Failed to allocate native buffer");

                        int result = NativeInterop.native_resize(
                            srcData.Scan0, srcWidth, srcHeight, srcData.Stride,
                            dstBuffer.Buffer, dstWidth, dstHeight, dstStride,
                            channels);

                        if (result != 0)
                            throw new InvalidOperationException($"Native resize failed: {result}");

                        byte[] output = new byte[dstStride * dstHeight];
                        Marshal.Copy(dstBuffer.Buffer, output, 0, output.Length);
                        return output;
                    }
                }
                finally
                {
                    srcBitmap.UnlockBits(srcData);
                }
            }
        }

        private byte[] PerformManagedResize(Image srcImage, int dstWidth, int dstHeight)
        {
            using (var dstBitmap = new Bitmap(dstWidth, dstHeight, PixelFormat.Format32bppArgb))
            using (var graphics = Graphics.FromImage(dstBitmap))
            {
                graphics.DrawImage(srcImage, 0, 0, dstWidth, dstHeight);
                using (var ms = new MemoryStream())
                {
                    dstBitmap.Save(ms, ImageFormat.Png);
                    return ms.ToArray();
                }
            }
        }
    }
}
